function extractLocale(file, locale) {
  const t = fs.readFileSync(
    path.join(__dirname, `../data/fc-translations/contents/${file}.ts`),
    "utf8",
  );
  const m = t.match(new RegExp(`const ${locale}Sections[\\s\\S]*?\\n\\];`));
  if (!m) return null;
  return Function(
    "return " + m[0].replace(`const ${locale}Sections: ServiceContentSection[] = `, ""),
  )();
}

